examples.code:
supply = 300
req = {"북미": 180, "유럽": 120, "아시아": 100}
prio = ["북미", "유럽", "아시아"]
left, by_prio = supply, {}
for r in prio:
    by_prio[r] = min(req[r], left)
    left -= by_prio[r]
print("우선순위 배분:", by_prio)
total = sum(req.values())
fair = {r: supply * q // total for r, q in req.items()}
print("비율 배분:", fair, "합계", sum(fair.values()))
# 우선순위 배분: {'북미': 180, '유럽': 120, '아시아': 0}
# 비율 배분: {'북미': 135, '유럽': 90, '아시아': 75} 합계 300
